package com.essde342.triggerbot.ui.modules; import com.essde342.triggerbot.ui.ISetting; import java.util.*; public class Module{private final String name,desc;private final Category category;private int bind=-1;private boolean enabled;private final Runnable cb;private final List<ISetting> settings=new ArrayList<>();public Module(String n,Category c,String d,boolean e,Runnable r){name=n;category=c;desc=d;enabled=e;cb=r;}public List<ISetting> getSettings(){return settings;}public void addSetting(ISetting s){settings.add(s);}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){if(enabled!=v){enabled=v;if(cb!=null)cb.run();}}public void toggled(){setEnabled(!enabled);}public String getName(){return name;}public Category getCategory(){return category;}public String getDesc(){return desc;}public int getBind(){return bind;}public void setBind(int b){bind=b;}}